namespace PsoBB.Save;

/// <summary>
/// The shipped static class tables: base stats at 0x00969188, growth caps at 0x00968560,
/// fallback level records at 0x009691A4 and the twelve 200-byte class level bytes behind
/// 0x009CC520.
/// </summary>
internal static class CharacterStatTables
{
	private static readonly byte[] BaseBytes = Convert.FromBase64String("AQABAAEAAQABAAEAAQAAAA==");
	private static readonly byte[] GrowthBytes = Convert.FromBase64String("");
	private static readonly byte[] LevelBytes = Convert.FromBase64String("");
	private static readonly byte[] ClassBytes = Convert.FromBase64String("");

	internal static ReadOnlySpan<byte> Base => BaseBytes;
	internal static ReadOnlySpan<byte> Growth => GrowthBytes;
	internal static ReadOnlySpan<byte> Levels => LevelBytes;
	internal static ReadOnlySpan<byte> Classes => ClassBytes;
}
